{
  "type": "object",
  "required": [
    "SchemeName",
    "Identification"
  ],
  "properties": {
    "SchemeName": {
      "type": "string",
      "enum": [
        "IBAN"
      ],
      "description": "Scheme name for the Debtor Account. The Debtor Account must be an IBAN."
    },
    "Identification": {
      "type": "string",
      "minLength": 1,
      "description": "The Identification of the Debtor Account."
    },
    "Name": {
      "type": "object",
      "properties": {
        "en": {
          "type": "string",
          "maxLength": 70
        },
        "ar": {
          "type": "string",
          "maxLength": 70
        }
      },
      "minProperties": 1,
      "description": "The Debtor Account, which can be provided in both English and Arabic. Omitted if not held by the TPP.",
      "additionalProperties": false
    }
  },
  "description": "Details of the Debtor Account when provided at the TPP. Omitted if not available at the TPP or the User chooses to select the Debtor Account at the LFI.",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "CreditorAccount"
  ],
  "properties": {
    "CreditorAgent": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AECreditorAgentProperties"
    },
    "Creditor": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AECreditorProperties"
    },
    "CreditorAccount": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEDomesticCreditorAccountProperties"
    },
    "ConfirmationOfPayeeResponse": {
      "type": "string",
      "pattern": "^.+\\..+\\..+$",
      "description": "Response from Confirmation of Payee operation, when executed for the Creditor Account.\n\nThis is JSON Web Signature returned by the Payee Confirmation operation at the Confirmation of Payee API.\n\nThe value must be the full JWS string, including the header and signature, without decoding to an object.\n\nIf Confirmation of Payee is not performed this property can be omitted"
    }
  },
  "description": "Identification elements for a Creditor for a domestic payment instruction.",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "SchemeName",
    "Identification"
  ],
  "properties": {
    "SchemeName": {
      "type": "string",
      "enum": [
        "BICFI",
        "Other"
      ]
    },
    "Identification": {
      "type": "string"
    },
    "Name": {
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "PostalAddress": {
      "$ref": "#/components/schemas/AEAddress"
    }
  },
  "description": "Properties of the Creditor Agent, which provides information on the Financial Institution that holds the Creditor Account.",
  "additionalProperties": false
}

{
  "anyOf": [
    {
      "description": "(Array) Address information that locates and identifes a specific address, as defined by a national or international postal service.\"\n**v1.2 version of address format marked as deprecated, replaced at v2.0**\n",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "AddressType",
          "Country"
        ],
        "properties": {
          "AddressType": {
            "$ref": "#/components/schemas/AEAddressTypeCode"
          },
          "ShortAddress": {
            "$ref": "#/components/schemas/AEShortAddress"
          },
          "UnitNumber": {
            "$ref": "#/components/schemas/AEUnitNumber"
          },
          "FloorNumber": {
            "$ref": "#/components/schemas/AEFloorNumber"
          },
          "BuildingNumber": {
            "$ref": "#/components/schemas/AEBuildingNumber"
          },
          "StreetName": {
            "$ref": "#/components/schemas/AEStreetName"
          },
          "SecondaryNumber": {
            "$ref": "#/components/schemas/AESecondaryNumber"
          },
          "District": {
            "$ref": "#/components/schemas/AEDistrict"
          },
          "PostalCode": {
            "$ref": "#/components/schemas/AEPostalCode"
          },
          "POBox": {
            "$ref": "#/components/schemas/AEPOBox"
          },
          "ZipCode": {
            "$ref": "#/components/schemas/AEZipCode"
          },
          "City": {
            "$ref": "#/components/schemas/AECity"
          },
          "Region": {
            "$ref": "#/components/schemas/AERegion"
          },
          "Country": {
            "$ref": "#/components/schemas/AECountryCode"
          }
        },
        "additionalProperties": false
      }
    },
    {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "AddressType": {
            "type": "string",
            "enum": [
              "Billing",
              "Business",
              "Correspondence",
              "DeliveryTo",
              "MailTo",
              "POBox",
              "Postal",
              "Permanent",
              "Residential",
              "Statement",
              "Other"
            ]
          },
          "AddressLine": {
            "type": "array",
            "items": {
              "type": "string",
              "minLength": 1,
              "maxLength": 70
            },
            "minItems": 1,
            "maxItems": 7
          },
          "BuildingNumber": {
            "type": "string",
            "minLength": 1,
            "maxLength": 16
          },
          "BuildingName": {
            "type": "string",
            "minLength": 1,
            "maxLength": 140
          },
          "Floor": {
            "type": "string",
            "minLength": 1,
            "maxLength": 70
          },
          "StreetName": {
            "type": "string",
            "minLength": 1,
            "maxLength": 140
          },
          "DistrictName": {
            "type": "string",
            "minLength": 1,
            "maxLength": 140
          },
          "PostBox": {
            "type": "string",
            "minLength": 1,
            "maxLength": 16
          },
          "TownName": {
            "type": "string",
            "minLength": 1,
            "maxLength": 140
          },
          "CountrySubDivision": {
            "anyOf": [
              {
                "type": "string",
                "enum": [
                  "AbuDhabi",
                  "Ajman",
                  "Dubai",
                  "Fujairah",
                  "RasAlKhaimah",
                  "Sharjah",
                  "UmmAlQuwain"
                ]
              },
              {
                "type": "string"
              }
            ]
          },
          "Country": {
            "type": "string",
            "pattern": "^[A-Z]{2}$"
          }
        },
        "required": [
          "AddressType",
          "AddressLine",
          "Country"
        ],
        "additionalProperties": false
      },
      "minItems": 1,
      "description": "One-or-more addresses related to a given subject."
    }
  ]
}

{
  "description": "Specifies the nature of the Address.",
  "type": "string",
  "enum": [
    "Business",
    "Correspondence",
    "Residential"
  ],
  "example": "Residential"
}

{
  "description": "Indicates the country code in which the address is located (References ISO 3166-1 alpha-2).",
  "type": "string",
  "pattern": "^[A-Z]{2,2}$",
  "example": "SA"
}

{
  "type": "object",
  "properties": {
    "Name": {
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "PostalAddress": {
      "$ref": "#/components/schemas/AEAddress"
    }
  },
  "description": "Party to which an amount of money is due.",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "SchemeName",
    "Identification",
    "Name"
  ],
  "properties": {
    "SchemeName": {
      "type": "string",
      "enum": [
        "IBAN"
      ],
      "description": "Domestic payment scheme, restricted to `IBAN`"
    },
    "Identification": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEIdentification"
    },
    "Name": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEName"
    },
    "TradingName": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AETradingName"
    },
    "Type": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AECreditorAccountTypeCodes"
    }
  },
  "description": "Unambiguous identification of the account of the creditor to which a credit entry will be posted.",
  "additionalProperties": false
}

{
  "type": "string",
  "minLength": 1,
  "description": "Identification for the account assigned by the LFI based on the Account Scheme Name.\nThis identification is known by the User account owner."
}

{
  "type": "object",
  "properties": {
    "en": {
      "type": "string",
      "maxLength": 70,
      "description": "English value of the string"
    },
    "ar": {
      "type": "string",
      "maxLength": 70,
      "description": "Arabic value of the string"
    }
  },
  "description": "The Account Holder Name is the name or names of the Account owner(s) represented at the account level",
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "en": {
      "type": "string",
      "maxLength": 70,
      "description": "English value of the string"
    },
    "ar": {
      "type": "string",
      "maxLength": 70,
      "description": "Arabic value of the string"
    }
  },
  "description": "The Trading Brand Name (if applicable) for the Creditor.\nApplicable to Payments.",
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "DebtorIndicators": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEDebtorIndicators"
    },
    "DestinationDeliveryAddress": {
      "type": "object",
      "properties": {
        "RecipientType": {
          "type": "string",
          "enum": [
            "Individual",
            "Corporate"
          ]
        },
        "RecipientName": {
          "type": "object",
          "properties": {
            "en": {
              "type": "string"
            },
            "ar": {
              "type": "string"
            }
          },
          "additionalProperties": false
        },
        "NationalAddress": {
          "$ref": "#/components/schemas/AEAddress"
        }
      },
      "description": "Destination Delivery Address",
      "additionalProperties": false
    },
    "TransactionIndicators": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AETransactionIndicators"
    },
    "CreditorIndicators": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AECreditorIndicators"
    }
  },
  "description": "The Risk section is sent by the TPP to the LFI. It is used to specify additional details for risk/fraud scoring regarding Payments.",
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "Authentication": {
      "type": "object",
      "properties": {
        "AuthenticationChannel": {
          "type": "string",
          "enum": [
            "App",
            "Web"
          ]
        },
        "PossessionFactor": {
          "type": "object",
          "properties": {
            "IsUsed": {
              "type": "boolean"
            },
            "Type": {
              "type": "string",
              "enum": [
                "FIDO2SecurityKey",
                "Passkey",
                "OTPDevice",
                "OTPApp",
                "SMSOTP",
                "EmailOTP",
                "PushNotification",
                "WebauthnToken",
                "SecureEnclaveKey",
                "HardwareOTPKey",
                "TrustedDevice",
                "Other"
              ]
            }
          },
          "additionalProperties": false
        },
        "KnowledgeFactor": {
          "type": "object",
          "properties": {
            "IsUsed": {
              "type": "boolean"
            },
            "Type": {
              "type": "string",
              "enum": [
                "PIN",
                "Password",
                "SecurityQuestion",
                "SMSOTP",
                "EmailOTP",
                "OTPPush",
                "Other"
              ]
            }
          },
          "additionalProperties": false
        },
        "InherenceFactor": {
          "type": "object",
          "properties": {
            "IsUsed": {
              "type": "boolean"
            },
            "Type": {
              "type": "string",
              "enum": [
                "Biometric",
                "Fingerprint",
                "FaceRecognition",
                "IrisScan",
                "VoiceRecognition",
                "FIDOBiometric",
                "DeviceBiometrics",
                "Other"
              ]
            }
          },
          "additionalProperties": false
        },
        "ChallengeOutcome": {
          "type": "string",
          "enum": [
            "Pass",
            "Fail",
            "NotPerformed"
          ]
        },
        "AuthenticationFlow": {
          "type": "string",
          "enum": [
            "MFA",
            "Other"
          ]
        },
        "AuthenticationValue": {
          "type": "string"
        },
        "ChallengeDateTime": {
          "type": "string",
          "format": "date-time"
        }
      },
      "description": "The authentication method used by the User to access their account with the TPP",
      "additionalProperties": false
    },
    "UserName": {
      "type": "object",
      "properties": {
        "en": {
          "type": "string"
        },
        "ar": {
          "type": "string"
        }
      },
      "description": "The Name of the User initiating the Payment",
      "additionalProperties": false
    },
    "GeoLocation": {
      "type": "object",
      "properties": {
        "Latitude": {
          "type": "string"
        },
        "Longitude": {
          "type": "string"
        }
      },
      "required": [
        "Latitude",
        "Longitude"
      ],
      "description": "GPS to identify and track the whereabouts of the connected electronic device.",
      "additionalProperties": false
    },
    "DeviceInformation": {
      "type": "object",
      "properties": {
        "DeviceId": {
          "type": "string"
        },
        "AlternativeDeviceId": {
          "type": "string"
        },
        "DeviceOperatingSystem": {
          "type": "string"
        },
        "DeviceOperatingSystemVersion": {
          "type": "string"
        },
        "DeviceBindingId": {
          "type": "string"
        },
        "LastBindingDateTime": {
          "type": "string",
          "format": "date-time"
        },
        "BindingDuration": {
          "type": "string",
          "format": "duration"
        },
        "BindingStatus": {
          "type": "string",
          "enum": [
            "Active",
            "Expired",
            "Revoked",
            "Suspended"
          ]
        },
        "DeviceType": {
          "type": "string",
          "enum": [
            "Mobile",
            "Desktop",
            "Tablet",
            "Wearable",
            "Other"
          ]
        },
        "DeviceManufacturer": {
          "type": "object",
          "properties": {
            "Model": {
              "type": "string",
              "maxLength": 50
            },
            "Manufacturer": {
              "type": "string",
              "maxLength": 50
            }
          },
          "additionalProperties": false
        },
        "DeviceLanguage": {
          "type": "string"
        },
        "DeviceLocalDateTime": {
          "type": "string"
        },
        "ConnectionType": {
          "type": "string",
          "enum": [
            "WiFi",
            "Cellular",
            "Other"
          ]
        },
        "ScreenInformation": {
          "type": "object",
          "properties": {
            "PixelDensity": {
              "type": "number"
            },
            "Orientation": {
              "type": "string",
              "enum": [
                "Portrait",
                "Landscape"
              ]
            }
          },
          "additionalProperties": false
        },
        "BatteryStatus": {
          "type": "object",
          "properties": {
            "Level": {
              "type": "number",
              "minimum": 0,
              "maximum": 100
            },
            "IsCharging": {
              "type": "boolean"
            }
          },
          "additionalProperties": false
        },
        "TouchSupport": {
          "type": "object",
          "properties": {
            "Supported": {
              "type": "boolean"
            },
            "MaxTouchPoints": {
              "type": "integer",
              "minimum": 0
            }
          },
          "additionalProperties": false
        },
        "MotionSensors": {
          "type": "object",
          "properties": {
            "Status": {
              "type": "string",
              "enum": [
                "InMotion",
                "Stationary"
              ]
            },
            "Accelerometer": {
              "type": "boolean"
            },
            "Gyroscope": {
              "type": "boolean"
            }
          },
          "additionalProperties": false
        },
        "DeviceEnvironmentContext": {
          "type": "array",
          "items": {
            "type": "string",
            "enum": [
              "VPNDetected",
              "EmulatorDetected"
            ]
          }
        }
      },
      "description": "Detailed device information",
      "additionalProperties": false
    },
    "BiometricCapabilities": {
      "type": "object",
      "properties": {
        "SupportsBiometric": {
          "type": "boolean"
        },
        "BiometricTypes": {
          "type": "array",
          "items": {
            "type": "string",
            "enum": [
              "Fingerprint",
              "FacialRecognition",
              "Iris",
              "VoicePrint",
              "Other"
            ]
          }
        }
      },
      "description": "Device biometric capabilities",
      "additionalProperties": false
    },
    "AppInformation": {
      "type": "object",
      "properties": {
        "AppVersion": {
          "type": "string"
        },
        "PackageName": {
          "type": "string"
        },
        "BuildNumber": {
          "type": "string"
        }
      },
      "description": "Mobile application specific information",
      "additionalProperties": false
    },
    "BrowserInformation": {
      "type": "object",
      "properties": {
        "UserAgent": {
          "type": "string"
        },
        "IsCookiesEnabled": {
          "type": "boolean"
        },
        "AvailableFonts": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "Plugins": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "PixelRatio": {
          "type": "number"
        }
      },
      "description": "Browser-specific information",
      "additionalProperties": false
    },
    "UserBehavior": {
      "type": "object",
      "properties": {
        "ScrollBehavior": {
          "type": "object",
          "properties": {
            "Direction": {
              "type": "string",
              "enum": [
                "Up",
                "Down",
                "Both"
              ]
            },
            "Speed": {
              "type": "number"
            },
            "Frequency": {
              "type": "number"
            }
          },
          "additionalProperties": false
        }
      },
      "description": "User behavior indicators",
      "additionalProperties": false
    },
    "AccountRiskIndicators": {
      "type": "object",
      "properties": {
        "UserOnboardingDateTime": {
          "type": "string",
          "format": "date-time"
        },
        "LastAccountChangeDate": {
          "type": "string",
          "format": "date"
        },
        "LastPasswordChangeDate": {
          "type": "string",
          "format": "date"
        },
        "SuspiciousActivity": {
          "type": "string",
          "enum": [
            "NoSuspiciousActivity",
            "SuspiciousActivityDetected"
          ]
        },
        "TransactionHistory": {
          "type": "object",
          "properties": {
            "LastDay": {
              "type": "integer",
              "minimum": 0
            },
            "LastYear": {
              "type": "integer",
              "minimum": 0
            }
          },
          "additionalProperties": false
        }
      },
      "description": "Risk indicators related to the account",
      "additionalProperties": false
    },
    "SupplementaryData": {
      "type": "object",
      "description": "Additional information that cannot be captured in the structured fields and/or any other specific block This\nmay include information that is not available in the structured fields, such as a user's behavioural data\nlike their typing speed and typing patterns."
    }
  },
  "description": "Debtor (User) Indicators",
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "IsCustomerPresent": {
      "type": "boolean",
      "description": "This field differentiates between automatic and manual payment initiation."
    },
    "IsContractPresent": {
      "type": "boolean",
      "description": "Indicates if the Creditor has a contractual relationship with the TPP."
    },
    "Channel": {
      "type": "string",
      "enum": [
        "Web",
        "Mobile"
      ],
      "description": "Where the payment has been initiated from."
    },
    "ChannelType": {
      "type": "string",
      "enum": [
        "ECommerce",
        "InStore",
        "InApp",
        "Telephone",
        "Mail",
        "RecurringPayment",
        "Other"
      ],
      "description": "The channel through which the transaction is being conducted"
    },
    "SubChannelType": {
      "type": "string",
      "enum": [
        "WebBrowser",
        "MobileApp",
        "SmartTV",
        "WearableDevice",
        "POSTerminal",
        "ATM",
        "KioskTerminal",
        "Other"
      ],
      "description": "More specific classification of the transaction channel"
    },
    "PaymentProcess": {
      "type": "object",
      "properties": {
        "TotalDuration": {
          "type": "integer",
          "minimum": 0
        },
        "CurrentSessionAttempts": {
          "type": "integer",
          "minimum": 1
        },
        "CurrentSessionFailedAttempts": {
          "type": "integer",
          "minimum": 0
        },
        "Last24HourAttempts": {
          "type": "integer",
          "minimum": 0
        },
        "Last24HourFailedAttempts": {
          "type": "integer",
          "minimum": 0
        }
      },
      "description": "Metrics related to the payment process duration and attempts",
      "additionalProperties": false
    },
    "MerchantRisk": {
      "type": "object",
      "properties": {
        "DeliveryTimeframe": {
          "type": "string",
          "enum": [
            "ElectronicDelivery",
            "SameDayShipping",
            "OvernightShipping",
            "MoreThan1DayShipping"
          ]
        },
        "ReorderItemsIndicator": {
          "type": "string",
          "enum": [
            "FirstTimeOrder",
            "Reorder"
          ]
        },
        "PreOrderPurchaseIndicator": {
          "type": "string",
          "enum": [
            "MerchandiseAvailable",
            "FutureAvailability"
          ]
        },
        "IsGiftCardPurchase": {
          "type": "boolean"
        },
        "IsDeliveryAddressMatchesBilling": {
          "type": "boolean"
        },
        "AddressMatchLevel": {
          "type": "string",
          "enum": [
            "FullMatch",
            "PartialMatch",
            "NoMatch",
            "NotApplicable"
          ]
        }
      },
      "description": "Risk indicator details provided by the merchant",
      "additionalProperties": false
    },
    "SupplementaryData": {
      "type": "object",
      "description": "Additional information that cannot be captured in the structured fields and/or any other specific block"
    }
  },
  "description": "Transaction Indicators",
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "AccountType": {
      "type": "string",
      "enum": [
        "Retail",
        "SME",
        "Corporate"
      ],
      "description": "Specifies the type of account (Retail, SME or Corporate)."
    },
    "IsCreditorPrePopulated": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEIsCreditorPrePopulated"
    },
    "TradingName": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AETradingName"
    },
    "IsVerifiedByTPP": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEIsVerifiedbyTPP"
    },
    "AdditionalAccountHolderIdentifiers": {
      "$ref": "#/components/schemas/AEAdditionalAccountHolderIdentifiers"
    },
    "MerchantDetails": {
      "type": "object",
      "properties": {
        "MerchantId": {
          "type": "string",
          "minLength": 8,
          "maxLength": 20
        },
        "MerchantName": {
          "type": "string",
          "minLength": 1,
          "maxLength": 350
        },
        "MerchantSICCode": {
          "type": "string",
          "minLength": 3,
          "maxLength": 4
        },
        "MerchantCategoryCode": {
          "type": "string",
          "minLength": 3,
          "maxLength": 4
        }
